def _append_note(current: str, addition: str) -> str:
    addition = (addition or "").strip()
    if not addition:
        return current or ""
    existing = (current or "").strip()
    if not existing:
        return addition
    if addition in existing:
        return existing
    return f"{existing} | {addition}"


