@app.post("/api/test-send", response_class=JSONResponse)
def api_test_send(
    payload: Dict[str, str],
    _: str = Depends(require_user),
) -> JSONResponse:
    content_source = payload.get("content_source", "").strip()
    if not content_source:
        raise HTTPException(
            status_code=status.HTTP_400_BAD_REQUEST,
            detail="content_source is required"
        )

    available_sources = content_source_factory.get_available_sources()
    if content_source not in available_sources:
        raise HTTPException(
            status_code=status.HTTP_400_BAD_REQUEST,
            detail=f"Invalid content_source. Available: {', '.join(available_sources)}"
        )

    try:
        import sjzl_daily_email as sjzl
        active_source = content_source_factory.get_source(content_source)

        subject = f"[TEST] Daily Manna - {active_source.get_display_name()}"
        body = f"This is a test send from {content_source}.\n\nIf you received this, the send flow is working correctly."

        recipients = sjzl.send_email(
            subject=subject,
            body=body,
            content_source=content_source
        )

        return JSONResponse({
            "success": True,
            "content_source": content_source,
            "recipient_count": len(recipients),
            "recipients": recipients,
            "message": f"Test send successful to {len(recipients)} subscriber(s)"
        })
    except ValueError as e:
        raise HTTPException(
            status_code=status.HTTP_400_BAD_REQUEST,
            detail=str(e)
        )
    except Exception as e:
        logger.error("Test send failed: %s", e)
        raise HTTPException(
            status_code=status.HTTP_500_INTERNAL_SERVER_ERROR,
            detail=f"Test send failed: {str(e)}"
        )

return app

