            sent_count = 0
            if result.stdout:
                # Try to extract message count from logs
                import re
                match = re.search(r"(\d+)\s+recipient", result.stdout)
                if match:
                    sent_count = int(match.group(1))

            message = f"✓ Test job '{job_name}' executed successfully"
            if result.stdout:
                message += f". See server logs for details."

            return JSONResponse({
                "status": "success",
                "message": message,
                "sent_count": sent_count,
            })
        finally:
            # Clear TEST_MODE flag
            os.environ.pop("TEST_MODE", None)

    except HTTPException:
        raise
    except Exception as e:
        logger.error("Test send failed: %s", e)
        raise HTTPException(
            status_code=status.HTTP_500_INTERNAL_SERVER_ERROR,
            detail=f"Test send failed: {str(e)}"
        )

