(function () {
  "use strict";

  const overlayEl = document.getElementById("test-send-overlay");
  const sourceSelectEl = document.getElementById("test-send-source");
  const sendBtn = document.getElementById("test-send-button");
  const feedbackEl = document.getElementById("test-send-feedback");
  const headerBtn = document.getElementById("test-send-btn");
  const closeButtons = overlayEl ? overlayEl.querySelectorAll(".test-send-close") : [];

  if (!overlayEl || !sourceSelectEl || !sendBtn || !headerBtn) {
    return;
  }

  let feedbackTimeout = null;

  const setFeedback = (type, message) => {
    feedbackEl.textContent = message;
    feedbackEl.classList.remove("is-success", "is-error");
    if (type === "success") {
      feedbackEl.classList.add("is-success");
    } else if (type === "error") {
      feedbackEl.classList.add("is-error");
    }

    if (feedbackTimeout) {
      clearTimeout(feedbackTimeout);
    }

    if (type === "success") {
      feedbackTimeout = setTimeout(() => {
        clearFeedback();
      }, 5000);
    }
  };

  const clearFeedback = () => {
    feedbackEl.textContent = "";
    feedbackEl.classList.remove("is-success", "is-error");
    if (feedbackTimeout) {
      clearTimeout(feedbackTimeout);
      feedbackTimeout = null;
    }
  };

  const loadContentSources = async () => {
    try {
      const response = await fetch("/api/dispatch-rules");
      if (!response.ok) {
        throw new Error("Failed to load content sources");
      }
      const data = await response.json();

      // Extract unique source names from dispatch rules
      const sources = new Set();
      if (data.rules && Array.isArray(data.rules)) {
        data.rules.forEach(rule => {
          // Try to infer content source from rule name or use dispatch config
        });
      }

      // Also fetch from content source factory if available
      try {
        const sourcesResponse = await fetch("/api/content-sources");
        if (sourcesResponse.ok) {
          const sourcesData = await sourcesResponse.json();
          if (sourcesData.sources && Array.isArray(sourcesData.sources)) {
            sourcesData.sources.forEach(s => sources.add(s));
          }
        }
      } catch (err) {
        // Fallback: use hardcoded sources
        ["ezoe", "wix", "stmn1"].forEach(s => sources.add(s));
      }

      // Populate dropdown
      sourceSelectEl.innerHTML = '<option value="">-- Select a source --</option>';
      Array.from(sources).sort().forEach(source => {
        const option = document.createElement("option");
        option.value = source;
        option.textContent = source;
        sourceSelectEl.appendChild(option);
      });
    } catch (error) {
      console.error("Failed to load content sources:", error);
      // Fallback: add hardcoded sources
      ["ezoe", "wix", "stmn1"].forEach(source => {
        const option = document.createElement("option");
        option.value = source;
        option.textContent = source;
        sourceSelectEl.appendChild(option);
      });
    }
  };

  const openOverlay = () => {
    // Hide all other overlays
    if (window.hideAllOverlaysExcept) {
      window.hideAllOverlaysExcept('test-send-overlay');
    }

    overlayEl.hidden = false;
    clearFeedback();
    loadContentSources();
  };

  const closeOverlay = () => {
    overlayEl.hidden = true;
  };

  const toggleOverlay = () => {
    if (overlayEl.hidden) {
      openOverlay();
    } else {
      closeOverlay();
    }
  };

  sendBtn.addEventListener("click", async () => {
    const source = sourceSelectEl.value.trim();
    if (!source) {
      setFeedback("error", "Please select a content source");
      return;
    }

    sendBtn.disabled = true;
    const originalText = sendBtn.textContent;
    sendBtn.textContent = "Sending...";

    try {
      const response = await fetch("/api/test-send", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ content_source: source }),
      });

      const data = await response.json();

      if (!response.ok) {
        throw new Error(data.detail || "Failed to send test email");
      }

      setFeedback("success", data.message);
      sourceSelectEl.value = "";
    } catch (error) {
      setFeedback("error", error.message || "Failed to send test email");
    } finally {
      sendBtn.disabled = false;
      sendBtn.textContent = originalText;
    }
  });

  headerBtn.addEventListener("click", (event) => {
    event.stopPropagation();
    toggleOverlay();
  });

  closeButtons.forEach(btn => {
    btn.addEventListener("click", (event) => {
      event.preventDefault();
      closeOverlay();
    });
  });

  document.addEventListener("click", (event) => {
    if (overlayEl.hidden) {
      return;
    }
    const target = event.target;
    if (overlayEl.contains(target) || headerBtn.contains(target)) {
      return;
    }
    closeOverlay();
  });

  document.addEventListener("keydown", (event) => {
    if (event.key === "Escape" && !overlayEl.hidden) {
      closeOverlay();
    }
  });
})();

